template<class Packet,class Model>inline void assert_joint_board_source_qualification(const Packet&,const std::filesystem::path&,const Model&);
inline eventio::Json joint_R_inner_native_query(const eventio::Json&p,std::size_t i){
 const auto&q=p.at("query");const auto uv=q.at("uv").get<Vec2<double>>(),n=q.at("n").get<Vec2<double>>();const auto alpha=q.at("alpha").get<std::vector<double>>();std::vector<Vec2<double>>points;for(double a:alpha)points.push_back({uv[0]+a*n[0],uv[1]+a*n[1]});
 return {{"row_index",i},{"source_factor_row_id",p.at("source_row_id")},{"alpha",alpha},{"native_uv",points},{"normal",n}};
}
template<class Packet>inline void assert_joint_R_inner_source_leaf(const Packet&p,const eventio::Json&cert,const eventio::Json&proofs,const std::filesystem::path&cp){
 using J=eventio::Json;using namespace accepted_aux_detail;const auto&doc=p.source_json;const std::size_t n=cert.at("original_raw_rows"),m=p.rows.size();auto check=[](bool ok,const char*why){if(!ok)throw std::runtime_error(std::string("strict R33 source prefix: ")+why);};check(m==n+33&&proofs.size()==33,"leaf source count differs");const auto&nq=doc.at("queries");const auto&nd=doc.at("source_station_domains");check(nq.size()>=33&&nd.at("rows").size()>=33,"leaf Query/domain missing");
 J oldR=J::array();for(const auto&d:nd.at("rows")){const auto i=d.at("row_index").template get<std::size_t>();if(i<n&&p.rows[i].material==73){oldR.push_back(d);check(p.rows[i].station_domain_path==d.at("path_index")&&p.rows[i].source_station_intervals==d.at("allowed_station_intervals").template get<std::vector<std::array<double,2>>>(),"old R19 typed station domain differs");}}check(oldR.size()==19&&digest(oldR)==cert.at("old_R19_source_domain_sha256"),"old R19 source domain changed");
 const auto alpha=prefix<double>(doc.at("arrays").at("alpha"),m),bounds=prefix<double>(doc.at("arrays").at("alpha_bounds"),2*m),quv=prefix<double>(doc.at("arrays").at("query_uv"),2*m);
 for(std::size_t j=0;j<33;++j){const auto i=n+j;const auto&f=proofs[j];joint_qualification_ref(f.at("source_packet"),cp.parent_path());const auto&r=p.rows[i];const auto expected=joint_R_inner_native_query(f,i);const auto&qseed=f.at("query");const auto uv=f.at("current_uv").get<Vec2<double>>(),normal=f.at("normal").get<Vec2<double>>();
 check(f.at("source_row_id").get<std::string>().rfind("Ad4_R_inner_curvature_v1/",0)==0&&(f.at("native_pts")==2206464||f.at("native_pts")==2321408)&&f.at("material_index")==73&&f.at("path_index")==0&&f.at("station_intervals")==J::array({J::array({.25,.75})})&&!f.at("point_correspondence").get<bool>()&&!f.at("entity_station_fixed").get<bool>()&&f.at("source_qualified").get<bool>()&&f.at("unknown_noise").get<bool>(),"frozen R proof role/scope differs");
 check(doc.at("source_row_ids")[i]==f.at("source_row_id")&&r.source_row_id==f.at("source_row_id")&&r.pts==f.at("native_pts")&&r.uv==uv&&r.normal==normal&&r.material==73&&r.path==0&&r.kind==0&&r.active&&r.shot_id=="s09"&&r.E==2&&r.stroke_pair_index==-1&&r.stroke_source_side==-1&&r.width_block==-1,"new R typed UV/ID/PTS/material/role differs");
 check(alpha[i]==f.at("measured_alpha")&&bounds[2*i]==-3&&bounds[2*i+1]==3&&quv[2*i]==qseed.at("uv")[0]&&quv[2*i+1]==qseed.at("uv")[1]&&nq[nq.size()-33+j]==expected&&r.query&&r.query->alpha==std::vector<double>{-3,3}&&r.query->uv==expected.at("native_uv").get<std::vector<Vec2<double>>>(),"new R finite original Query/alpha/source window differs");
 const J domain={{"row_index",i},{"path_index",0},{"allowed_station_intervals",J::array({J::array({.25,.75})})},{"source_row_id",f.at("source_row_id")}};check(nd.at("rows")[nd.at("rows").size()-33+j]==domain&&r.station_domain_path==0&&r.source_station_intervals==std::vector<std::array<double,2>>{{.25,.75}},"new R source finite station union redirected");}
}
template<class Packet,class Model>inline void assert_joint_R_inner_source_prefix(const Packet&p,const std::filesystem::path&packet,const Model&actual_model){
 using J=eventio::Json;using namespace accepted_aux_detail;const auto&doc=p.source_json;const auto cp=joint_qualification_ref(doc.at("board_material_source_qualification"),packet.parent_path());const auto cert=eventio::read_json(cp);
 auto check=[](bool ok,const char*why){if(!ok)throw std::runtime_error(std::string("strict R33 source prefix: ")+why);};
 check(cert.at("schema")=="rinkfit.actual_R_inner_source_after_bound_V9_prefix.v1"&&cert.at("parent_recursion_contract")=="actual_33_R_inner_finite_source_after_CP_bound_V9_v1","schema/explicit V9 recursion contract differs");
 check(cert.at("issuer_module_ref").at("sha256")=="3a6866b74aa9f76e51716da86b74c9e659468da39ee9badf14fe051a2a4368eb"&&cert.at("recursive_parent_guard_module_ref").at("sha256")=="5786702f2673f48af1890ae1d934b6f21cf4fc867507abd5008a02a9c11ba361"&&cert.at("source_reader_module_ref").at("sha256")=="bfc8c0e8d565df7e95d8a8549dfe3f1fefaf9081c07c0700688bf40c886f7ae9"&&cert.at("source_qualification_issuer").at("sha256")=="b0dbff45e499ad34fe8c687cf673d6ad4483fb0693522549a5167f52fee05c2b","executed issuer/reader/strict qualifier changed");
 for(const char*k:{"issuer_module_ref","recursive_parent_guard_module_ref","source_reader_module_ref","source_qualification_issuer","actual_append_source_bundle","source_manifest","parent_model"})joint_qualification_ref(cert.at(k),cp.parent_path());
 check(cert.at("strict_source_qualification").at("sha256")=="903055c01267062bd75caf336b40e761ef6b5a92d0b162291ae500d1fee0f54d"&&cert.at("source_manifest").at("sha256")=="ebae14abd504cd116c078933bb17841edaf0189da58f6faf4b00b88a2ffe8b0e","frozen source qualification/manifest redirected");
 const auto fingerprint=joint_source_membership_fingerprint(doc);for(const auto&dependency:cert.at("runtime_inherited_source_recall_dependencies")){const auto file=joint_qualification_ref(dependency,cp.parent_path());bool found=false;for(const auto&watch:doc.value("source_identity_watchlist",J::array()))if(watch.value("source_membership_fingerprint",std::string{})==fingerprint&&watch.at("sha256")==dependency.at("sha256")&&joint_qualification_ref(watch,packet.parent_path())==file){found=true;break;}check(found,"inherited runtime recall dependency missing");}
 const auto q=eventio::read_json(joint_qualification_ref(cert.at("strict_source_qualification"),cp.parent_path()));const auto&proofs=q.at("actual_source_proofs");
 check(q.at("schema")=="rinkfit.R_inner_curvature_strict_source_gate.v1"&&q.at("raw_rows")==40&&q.at("qualified_source_rows")==33&&proofs.size()==33&&q.at("pending_rows").size()==7&&!q.at("old_R19_scope_changed").get<bool>()&&!q.at("noise_precision_issued").get<bool>()&&q.at("source_and_query_and_station_domain_frozen").get<bool>()&&q.at("exact_frozen_RGB_replay_max_px")==0,"incomplete exact frozen R33 source qualification");
 assert_joint_R_inner_source_leaf(p,cert,proofs,cp);
 const auto pp=joint_qualification_ref(cert.at("parent_packet"),cp.parent_path());const auto parent=Packet::load(pp.string(),actual_model);assert_joint_board_source_qualification(parent,pp,actual_model);const auto&old=parent.source_json;
 check(old.at("accepted_explicit_state_binding").at("schema")=="rinkfit.accepted_operator_transition_state_packet_binding.v1","parent does not explicitly retain V9 complete-state contract");
 const std::size_t n=parent.rows.size(),m=p.rows.size();check(m==n+33&&cert.at("original_raw_rows")==n&&cert.at("raw_rows")==m&&cert.at("appended_raw_rows")==33&&cert.at("inherited_material_count")==actual_model.materials.size()&&cert.at("inherited_physical_block_count")==actual_model.blocks.size(),"source scope/model count differs");
 check(doc.at("material_binding")==old.at("material_binding")&&doc.at("shot_ids")==old.at("shot_ids"),"old material/native clock differs");
 for(const auto&root:{pp.parent_path(),cp.parent_path()})for(const char*k:{"SOURCE_IDENTITY_CERTIFICATE_RECALLED.json","SOURCE_IDENTITY_EVIDENCE_RECALL.json"})check(!std::filesystem::exists(root/k),"source evidence recalled");
 for(const char*k:{"source_row_ids","source_dataset_ids","source_family_ids"}){check(doc.at(k).size()==m&&old.at(k).size()==n,"source identity denominator differs");for(std::size_t i=0;i<n;++i)check(doc.at(k)[i]==old.at(k)[i],"inherited source identity changed");}
 for(const char*k:{"independent_rows","independent_statistic_kind","joint_statistics_rank","stroke_pairs"})check(doc.value(k,J{})==old.value(k,J{}),"old statistics or actual pair scope changed");
 check(doc.at("arrays").size()==old.at("arrays").size(),"array ABI set differs");
 for(auto it=old.at("arrays").begin();it!=old.at("arrays").end();++it){const auto&a=it.value();const auto&b=doc.at("arrays").at(it.key());auto shape=a.at("shape").get<std::vector<std::size_t>>();check(shape.size()>0&&shape[0]==n&&a.at("dtype")==b.at("dtype"),"array dtype/parent shape differs");shape[0]=m;check(b.at("shape")==shape,"appended array shape differs");const auto x=eventio::bytes(joint_qualification_ref(a,pp.parent_path())),y=eventio::bytes(joint_qualification_ref(b,packet.parent_path()));std::size_t bytes=n*dtype_size(a.at("dtype"));for(std::size_t k=1;k<shape.size();++k)bytes*=shape[k];const auto xo=a.value("offset_bytes",std::size_t{}),yo=b.value("offset_bytes",std::size_t{});check(x.size()>=xo+bytes&&y.size()>=yo+bytes&&!std::memcmp(x.data()+xo,y.data()+yo,bytes),"inherited source or all-four auxiliary array prefix changed");}
 const auto&oq=old.at("queries");const auto&nq=doc.at("queries");check(nq.size()==oq.size()+33,"Query count differs");for(std::size_t j=0;j<oq.size();++j)check(nq[j]==oq[j],"old original Query changed");
 const auto&od=old.at("source_station_domains");const auto&nd=doc.at("source_station_domains");check(nd.at("rows").size()==od.at("rows").size()+33,"finite domain count differs");J oldR=J::array();for(std::size_t j=0;j<od.at("rows").size();++j){const auto&d=od.at("rows")[j];check(nd.at("rows")[j]==d,"old R19 finite station union changed");const auto i=d.at("row_index").get<std::size_t>();check(p.rows[i].station_domain_path==parent.rows[i].station_domain_path&&p.rows[i].source_station_intervals==parent.rows[i].source_station_intervals,"old typed finite station union changed");if(parent.rows[i].material==73)oldR.push_back(d);}check(oldR.size()==19&&digest(oldR)==cert.at("old_R19_source_domain_sha256"),"old R19 original domain identity differs");
 const auto&og=old.at("groups");const auto&ng=doc.at("groups");check(ng.size()>=og.size(),"lost old W/groups");for(std::size_t j=0;j<og.size();++j){auto a=og[j],b=ng[j];for(auto*v:{&a,&b})if(v->at("W").is_object())(*v)["W"].erase("file");check(a==b,"old exact W/group changed");}std::vector<unsigned char>partition(33,0);for(std::size_t j=og.size();j<ng.size();++j){const auto&g=ng[j];check(g.at("statistic_kind")=="constraint_only_unknown_noise"&&g.at("rank")==0&&g.at("W")==J::array()&&!g.value("unknown_noise_source_has_statistical_precision",true),"new R invented precision");for(const auto&v:g.at("rows")){auto i=v.get<std::size_t>();check(i>=n&&i<m&&++partition[i-n]==1,"new R partition differs");}}for(auto v:partition)check(v==1,"incomplete new R partition");
 const auto&binding=doc.at("accepted_explicit_state_binding");const auto state=eventio::read_json(joint_qualification_ref(binding.at("prefix_contract"),packet.parent_path()));check(binding.at("schema")=="rinkfit.accepted_R_inner_source_append_state_packet_binding.v1"&&state.at("schema")=="rinkfit.R_inner_append_inherited_engineering_state_contract.v1"&&binding.at("parent_packet")==cert.at("parent_packet")&&state.at("parent_packet")==cert.at("parent_packet")&&state.at("parent_accepted_binding")==old.at("accepted_explicit_state_binding")&&state.at("current_model")==cert.at("parent_model")&&state.at("new_source_qualification")==doc.at("board_material_source_qualification")&&binding.at("inherited_parent_raw_rows")==n&&binding.at("state_token")==old.at("accepted_explicit_state_binding").at("state_token"),"complete-state parent inheritance redirected");
}
